$worker=static function(array $data):array {$proc=proc_open([PHP_BINARY,__DIR__.'/m09-worker.php'],[0=>['pipe','r'],1=>['pipe','w'],2=>['file','/dev/null','a']],$pipes,dirname(__DIR__));m09check(is_resource($proc),'Cannot start worker');fwrite($pipes[0],json_encode($data,JSON_THROW_ON_ERROR)."\n");fflush($pipes[0]);stream_set_timeout($pipes[1],10);m09check(trim((string)fgets($pipes[1]))==='READY','Worker not ready');return [$proc,$pipes];};
